import json

# Pattern: swap 2↔9 in columns 0,1,3 only; col 4 stays as is; 4s stay as 4
output = []
for row in grid:
    new_row = []
    for col_idx, val in enumerate(row):
        if val == 4:
            new_row.append(4)
        elif col_idx == 4:
            new_row.append(val)  # col 4 unchanged
        else:
            new_row.append(2 if val == 9 else 9 if val == 2 else val)
    output.append(new_row)

print("Pattern: swap 2↔9 only in cols 0,1,3 (col 4 unchanged, 4s stay):")
for row in output:
    print(row)
print(json.dumps({"action": "submit", "grid": output}))

import json

# Pattern: min of each row pair, duplicated
output = []
for r in range(0, 8, 2):
    row_pair_output = []
    for c in range(5):
        if grid[r][c] == 4:
            row_pair_output.append(4)
        else:
            row_pair_output.append(min(grid[r][c], grid[r+1][c]))
    output.append(row_pair_output)
    output.append(row_pair_output.copy())

print("Pattern: min of each row pair, duplicated:")
for row in output:
    print(row)
print(json.dumps({"action": "submit", "grid": output}))
